class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        reach = [{0} for _ in range(n)]

        def all_ok():
            for i in range(n):
                if nums[i] not in reach[i]:
                    return False
            return True

        if all_ok():
            return 0

        for k, (l, r, v) in enumerate(queries):
            for i in range(l, r + 1):
                cur = reach[i]
                new = set(cur)
                for s in cur:
                    t = s + v
                    if t <= nums[i]:
                        new.add(t)
                reach[i] = new
            if all_ok():
                return k + 1

        return -1
