        n = len(nums)
        # reach[j] = bitmask of achievable total decrements at index j
        reach = [1] * n  # bit 0 set: sum 0 achievable

        def all_ok():
            for j in range(n):
                if not (reach[j] >> nums[j]) & 1:
                    return False
            return True

        if all_ok():
            return 0

        for k, (l, r, v) in enumerate(queries):
            for j in range(l, r + 1):
                # subset-sum update: either take v or not
                reach[j] |= reach[j] << v
                # cap bits to avoid unbounded growth
                reach[j] &= (1 << (nums[j] + 1)) - 1
            if all_ok():
                return k + 1
        return -1
