def _feasible(nums, qs):
    # Each index i independently: choose a subset of the queries covering i
    # (each query applies to index i at most once) whose vals sum to nums[i].
    for i, target in enumerate(nums):
        covering = [v for (l, r, v) in qs if l <= i <= r]
        found = False
        for mask in itertools.product((False, True), repeat=len(covering)):
            s = sum(v for v, use in zip(covering, mask) if use)
            if s == target:
                found = True
                break
        if not found:
            return False
    return True


